function N({registerIndicator:b,nulls:p}){b({id:"oa-cmf",name:"Chaikin Money Flow (CMF)",category:"Volume",placement:"pane",inputs:[{key:"length",type:"number",label:"Length",default:20,min:1,max:5e3,step:1}],plots:[{key:"cmf",type:"line",title:"CMF",style:{color:"#ffeb3b",lineWidth:2}}],calc(r,F){const l=Math.max(1,Math.floor(Number(F.length)||20)),n=r.length,m=new Array(n).fill(0),s=new Array(n).fill(0),u=new Array(n).fill(NaN);let f=0,c=0;for(let e=0;e<n;e++){const t=r[e],o=t.high,i=t.low,a=t.close;let h=0;Number.isFinite(o)&&Number.isFinite(i)&&Number.isFinite(a)&&(h=o!==i?(a-i-(o-a))/(o-i):0);const y=Number.isFinite(t.volume)?t.volume:0;m[e]=h*y,s[e]=y,f+=m[e]-(e>=l?m[e-l]:0),c+=s[e]-(e>=l?s[e-l]:0),u[e]=c!==0?f/c:0}return{cmf:p(u)}}})}export{N as default};
